preset.customCSS:
@import url("https://fonts.googleapis.com/css2?family=Noto+Serif+KR:wght@400;600;700&display=swap");

/* 바깥 래퍼: 메시지 폭을 확보하고 가운데 정렬합니다. */
.risu-chat > div {
  padding: 0;
  margin: auto;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-items: center;
  width: 100%;
  min-width: 0;
}
.risu-chat > div > div {
  width: 100%;
  min-width: 0;
  margin: auto;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
}

/* 글꼴과 크기: 본문 글자 크기는 --rtbook-font-size로 바꿉니다. */
.rtbook {
  --rtbook-bg-fill: transparent;
  --rtbook-bg-border: 0;
  --rtbook-blur: none;
  --rtbook-bg-edge: none;
  --rtbook-bg-sheen: linear-gradient(transparent, transparent);
  --rtbook-bg-fallback: transparent;
  --rtbook-font-body: "Noto Serif KR", "Nanum Myeongjo", "Batang", serif;
  --rtbook-font-display: "Noto Serif KR", "Nanum Myeongjo", "Batang", serif;
  --rtbook-font-size: 17px;
  --rtbook-line-height: 1.9;
  --rtbook-para-gap: .9em;
  --rtbook-measure: 36em;
  --rtbook-indent: 1em;
  --rtbook-dialog-weight: 600;
  --rtbook-ornament: "⁂";
}

/* 본문: RisuAI 기본 색·글꼴 변수에 테마 값을 연결합니다. */
.rtbook {
  --risu-font-family: var(--rtbook-font-body);
  --FontColorStandard: var(--rtbook-ink);
  --FontColorBold: var(--rtbook-strong, var(--rtbook-ink));
  --FontColorItalic: var(--rtbook-muted);
  --FontColorItalicBold: var(--rtbook-muted);
  --FontColorQuote1: var(--rtbook-muted);
  --FontColorQuote2: var(--rtbook-dialog);
  position: relative;
  isolation: isolate;
  width: 100%;
  min-width: 0;
  color: var(--rtbook-ink);
  font-family: var(--rtbook-font-body);
  font-size: var(--rtbook-font-size);
  line-height: var(--rtbook-line-height);
  letter-spacing: var(--rtbook-tracking, -.005em);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}
.rtbook, .rtbook *, .rtbook *::before, .rtbook *::after { box-sizing: border-box; }
/* 바깥 래퍼 보정(.risu-chat > div > div)이 테마 루트를 flex로 바꾸지 않게 루트 배치를 고정합니다. */
.rtbook.rtbook { display: block; }
.rtbook ::selection { background: color-mix(in srgb, var(--rtbook-accent) 26%, transparent); color: inherit; }
.rtbook__content {
  min-width: 0;
  color: var(--rtbook-ink);
  word-break: keep-all;
  overflow-wrap: break-word;
  text-wrap: pretty;
}
.rtbook__content .chattext {
  --tw-prose-code: var(--rtbook-strong, var(--rtbook-ink));
  --tw-prose-pre-code: var(--rtbook-ink);
  --tw-prose-pre-bg: var(--rtbook-tint);
  max-width: none;
  color: var(--rtbook-ink);
  font-size: var(--rtbook-font-size) !important;
  line-height: var(--rtbook-line-height) !important;
}
/* :where()로 우선순위를 낮춰 캐릭터 카드 자체 HTML 스타일이 이기게 합니다. */
.rtbook__content :where(p, li, td, th, blockquote) {
  font-size: var(--rtbook-font-size);
  line-height: var(--rtbook-line-height);
}
.rtbook__content :where(p) { margin: 0 0 var(--rtbook-para-gap); }
.rtbook__content :where(p:last-child) { margin-bottom: 0; }
.rtbook__content :where(h1, h2, h3, h4, h5, h6) {
  --risu-font-family: var(--rtbook-font-display);
  margin: 1.35em 0 .55em;
  color: var(--rtbook-strong, var(--rtbook-ink));
  font-family: var(--rtbook-font-display);
  line-height: 1.35;
  letter-spacing: -.015em;
  font-weight: 700;
}
.rtbook__content :where(h1, h2, h3, h4, h5, h6):where(:first-child) { margin-top: .15em; }
.rtbook__content :where(h1) { font-size: calc(var(--rtbook-font-size) * 1.55); }
.rtbook__content :where(h2) { font-size: calc(var(--rtbook-font-size) * 1.32); }
.rtbook__content :where(h3) { font-size: calc(var(--rtbook-font-size) * 1.15); }
.rtbook__content :where(h4, h5, h6) { font-size: var(--rtbook-font-size); color: var(--rtbook-muted); }
.rtbook__content :where(strong) { font-weight: 700; color: var(--rtbook-strong, var(--rtbook-ink)); }
/* 한글은 기울임 글꼴이 없어 가짜 기울임 대신 색으로만 구분합니다. */
.rtbook__content :where(em) { font-style: normal; color: var(--rtbook-muted); }
.rtbook__content mark[risu-mark="quote1"],
.rtbook__content mark[risu-mark="blockquote1"] { color: var(--rtbook-muted); background: transparent; }
.rtbook__content mark[risu-mark="quote2"],
.rtbook__content mark[risu-mark="blockquote2"] {
  color: var(--rtbook-dialog);
  font-weight: var(--rtbook-dialog-weight);
  background: transparent;
}
.rtbook__content :where(blockquote) {
  margin: 1em 0;
  padding: .55em 1.05em;
  border-left: 2.5px solid var(--rtbook-accent);
  border-radius: 0 .5rem .5rem 0;
  background: var(--rtbook-tint);
  color: var(--rtbook-muted);
}
.rtbook__content :where(ul, ol) { margin: .85em 0; padding-left: 1.45em; }
.rtbook__content :where(li) { margin: .28em 0; padding-left: .12em; color: var(--rtbook-ink); }
.rtbook__content :where(li)::marker { color: var(--rtbook-accent); }
.rtbook__content :where(a) {
  color: var(--rtbook-accent);
  text-decoration: underline;
  text-decoration-color: color-mix(in srgb, var(--rtbook-accent) 45%, transparent);
  text-underline-offset: 3px;
}
.rtbook__content :where(a:hover) { text-decoration-color: currentColor; }
.rtbook__content :where(hr) {
  height: 1px;
  border: 0;
  margin: 1.55em 0;
  background: linear-gradient(90deg, transparent, var(--rtbook-line) 15%, var(--rtbook-line) 85%, transparent);
}
.rtbook__content :where(code) {
  --risu-font-family: "IBM Plex Mono", "JetBrains Mono", ui-monospace, Consolas, monospace;
  padding: .12em .38em;
  border-radius: .3em;
  color: var(--rtbook-strong, var(--rtbook-ink));
  background: var(--rtbook-tint);
  font-family: "IBM Plex Mono", "JetBrains Mono", ui-monospace, Consolas, monospace;
  font-size: calc(var(--rtbook-font-size) * .88);
  line-height: 1.5;
}
.rtbook__content :where(pre) {
  max-width: 100%;
  overflow-x: auto;
  margin: 1em 0;
  padding: .9em 1.05em;
  color: var(--rtbook-ink);
  background: var(--rtbook-tint);
  border: 1px solid var(--rtbook-line);
  border-radius: .5rem;
  font-size: calc(var(--rtbook-font-size) * .88);
  line-height: 1.55;
}
.rtbook__content :where(pre code) { padding: 0; background: transparent; color: inherit; white-space: pre; overflow-wrap: normal; }
.rtbook__content :where(table) {
  display: block;
  width: 100%;
  max-width: 100%;
  overflow-x: auto;
  border-collapse: collapse;
  margin: 1em 0;
}
.rtbook__content :where(th, td) {
  padding: .52em .78em;
  color: var(--rtbook-ink);
  border-bottom: 1px solid var(--rtbook-line);
  text-align: left;
  vertical-align: top;
}
.rtbook__content :where(th) {
  background: var(--rtbook-tint);
  color: var(--rtbook-strong, var(--rtbook-ink));
  font-weight: 600;
}
.rtbook__content :where(img) { display: block; max-width: 100%; height: auto; margin: .75em auto; border-radius: .55rem; }
.rtbook__content textarea.message-edit-area {
  width: 100%;
  max-width: 100%;
  min-width: 0;
  min-height: 6rem;
  padding: .75rem .9rem;
  resize: vertical;
  color: var(--rtbook-ink) !important;
  background: var(--rtbook-edit-bg) !important;
  border: 1px solid var(--rtbook-line);
  border-radius: .55rem;
  font: inherit;
  font-size: var(--rtbook-font-size) !important;
  line-height: var(--rtbook-line-height) !important;
  transition: border-color .15s ease, box-shadow .15s ease;
}
.rtbook__content textarea.message-edit-area:focus {
  outline: none;
  border-color: var(--rtbook-accent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--rtbook-accent) 18%, transparent);
}

/* 조작부: 생성 정보와 Risu 기본 버튼만 다듬고, 서드파티 플러그인 버튼 모양은 유지합니다. */
.rtbook__footer {
  /* RisuAI(Tailwind v4)는 버튼 색을 --color-textcolor2로 칠하고, 이 변수는 페이지 맨 위에서 이미 앱 설정 색으로 정해져 있습니다.
     --risu-theme-textcolor2만 바꾸면 버튼은 앱 색으로 남아 종이·어두운 바탕에서 보이지 않으므로, 버튼이 실제로 쓰는 변수를 여기서 다시 정합니다. */
  --risu-theme-textcolor2: var(--rtbook-muted);
  --color-textcolor2: var(--rtbook-muted);
  --color-textcolor: var(--rtbook-ink);
  --color-darkborderc: var(--rtbook-line);
  --color-darkbutton: var(--rtbook-line);
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: .4rem .75rem;
  min-width: 0;
  color: var(--rtbook-muted);
}
.rtbook__info, .rtbook__actions { min-width: 0; max-width: 100%; }
.rtbook__info > div, .rtbook__actions > div { display: flex; flex-wrap: wrap; align-items: center; min-width: 0; gap: .25rem; color: var(--rtbook-muted); }
.rtbook__actions > div > div { display: flex; flex-wrap: wrap; align-items: center; min-width: 0; gap: .05rem; }
.rtbook__info button.transition-all,
.rtbook__actions button[class*="button-icon-"] {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  min-width: 1.9rem;
  min-height: 1.9rem;
  padding: .28rem;
  border-radius: 999px;
  background: transparent;
  transition: background-color .15s ease, color .15s ease;
}
.rtbook__info button.transition-all:hover,
.rtbook__actions button[class*="button-icon-"]:hover { background: var(--rtbook-tint); color: var(--rtbook-ink); }
.rtbook__info button:not(.transition-all) {
  background: transparent;
  color: inherit;
  border: 1px solid var(--rtbook-line);
  padding: .18rem .5rem;
  border-radius: .35rem;
  font-size: .92em;
  transition: background-color .15s ease, color .15s ease;
}
.rtbook__info button:not(.transition-all):hover { background: var(--rtbook-tint); color: var(--rtbook-ink); }
.rtbook :where(a, button, textarea):focus-visible { outline: 2px solid var(--rtbook-accent); outline-offset: 2px; }

/* 아바타 틀: RisuAI가 넣는 배경 이미지 칸을 틀에 맞춥니다. */
.rtbook__portrait { overflow: hidden; background: var(--rtbook-tint); }
.rtbook__portrait > * {
  width: 100% !important;
  height: 100% !important;
  min-width: 0 !important;
  min-height: 0 !important;
  background-size: cover !important;
  background-position: center 22% !important;
  border: 0 !important;
  border-radius: inherit !important;
}

@media (prefers-reduced-motion: reduce) {
  .rtbook, .rtbook * { transition: none !important; animation: none !important; }
}
@media (prefers-reduced-transparency: reduce) {
  .rtbook .rtbook__bg {
    background: var(--rtbook-bg-fallback, var(--rtbook-bg-fill));
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
  }
}
@supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {
  .rtbook .rtbook__bg { background: var(--rtbook-bg-fallback, var(--rtbook-bg-fill)); }
}

.rtbook__bg {
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  border-radius: inherit;
  background: var(--rtbook-bg-fill);
  border: var(--rtbook-bg-border, 0);
  -webkit-backdrop-filter: var(--rtbook-blur);
  backdrop-filter: var(--rtbook-blur);
  box-shadow: var(--rtbook-bg-edge);
}

/* 구조: 종이책 */

.rtbook {
  background: var(--rtbook-outer);
  padding: var(--rtbook-wrap-y, 0px) clamp(.75rem, 4vw, 2.5rem);
}
.rtbook__page {
  position: relative;
  max-width: var(--rtbook-measure);
  margin: 0 auto;
  padding: 1.55rem var(--rtbook-page-px, 1.5rem) 1.1rem;
  border-radius: var(--rtbook-page-r, 0px);
}
.rtbook .rtbook__bg { background: var(--rtbook-bg-sheen), var(--rtbook-paper); }
@media (min-width: 900px) {
  .rtbook__page {
    box-shadow: -16px 0 22px -18px var(--rtbook-gutter), 16px 0 22px -18px var(--rtbook-gutter);
  }
}
.rtbook__ornament {
  display: flex;
  align-items: center;
  gap: .9rem;
  margin-bottom: 1.05rem;
  color: var(--rtbook-accent);
  font-size: clamp(.9em, 1.4vw, 1.12em);
  opacity: .88;
}
.rtbook__ornament::before, .rtbook__ornament::after {
  content: "";
  flex: 1 1 auto;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--rtbook-line));
}
.rtbook__ornament::after { background: linear-gradient(90deg, var(--rtbook-line), transparent); }
.rtbook__ornament > span::before { content: var(--rtbook-ornament); }
.rtbook--user .rtbook__ornament { display: none; }
.rtbook__name {
  margin-bottom: .75rem;
  color: var(--rtbook-muted);
  font-size: .75em;
  letter-spacing: .16em;
  text-transform: uppercase;
}
.rtbook--user .rtbook__page { padding-top: .5rem; padding-bottom: .65rem; }
.rtbook--user .rtbook__name { display: none; }
.rtbook--user .rtbook__content {
  margin-left: 1.1em;
  padding-left: 1em;
  border-left: 2px solid var(--rtbook-accent);
  opacity: .92;
}
.rtbook--user .rtbook__content .chattext,
.rtbook--user .rtbook__content :where(p, li) {
  color: var(--rtbook-muted) !important;
  font-size: calc(var(--rtbook-font-size) * .9) !important;
}
.rtbook__content :where(p) { text-indent: var(--rtbook-indent); }
.rtbook__content :where(p:first-child, h1 + p, h2 + p, h3 + p, h4 + p, h5 + p, h6 + p, blockquote + p, ul + p, ol + p, pre + p, table + p, hr + p) { text-indent: 0; }
.rtbook--user .rtbook__content :where(p) { text-indent: 0; }
.rtbook__footer { margin-top: .55rem; }

.rtbook__footer { opacity: .7; transition: opacity .2s ease; }
.rtbook:hover .rtbook__footer, .rtbook:focus-within .rtbook__footer, .rtbook:has(textarea.message-edit-area) .rtbook__footer { opacity: 1; }
/* 휴대폰처럼 마우스를 올릴 수 없는 화면에서는 늘 또렷하게 둡니다. */
@media (hover: none) { .rtbook__footer { opacity: 1; } }

/* 짧은 대화: 맨 위 메시지 위쪽 빈 곳도 같은 바탕으로 칠합니다. */
.default-chat-screen > .risu-chat .rtbook,
.chat-message-container:last-child .rtbook { box-shadow: 0 -100vh 0 100vh var(--rtbook-outer); }
/* 첫인사 위에 RisuAI가 붙이는 안내문(AI 생성 안내, 제작자 메모)이 칠한 바탕 아래로 숨지 않게 합니다. */
:where(.default-chat-screen > .risu-chat:has(.rtbook) ~ *) { position: relative; }

/* ── 배색과 소재: 이 블록만 바꾸면 같은 분류의 다른 변주가 됩니다. (크림) ── */
.rtbook {
  --rtbook-outer: #efe8da;
  --rtbook-paper: #f7f2e7;
  --rtbook-ink: #2d2924;
  --rtbook-strong: #191612;
  --rtbook-muted: #776d60;
  --rtbook-accent: #8c6645;
  --rtbook-dialog: #241e18;
  --rtbook-line: #dcd1be;
  --rtbook-tint: #ebe2d1;
  --rtbook-edit-bg: #fcf8ef;
  --rtbook-gutter: rgba(72, 52, 24, .11);
  --rtbook-wrap-y: 0px;
  --rtbook-page-r: 0px;
  --rtbook-page-px: clamp(1.25rem, 3vw, 2.5rem);
}
